(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,23541,e=>{"use strict";var i=e.i(43476),l=e.i(11337);function n(e){let n={li:"li",p:"p",strong:"strong",ul:"ul",...(0,l.useMDXComponents)(),...e.components},{AnketaCollapse:r,AnketaGroup:c,AnketaList:d,AnketaPoint:h,AnketaProse:j,Whisper:x}=n;return r||s("AnketaCollapse",!0),c||s("AnketaGroup",!0),d||s("AnketaList",!0),h||s("AnketaPoint",!0),j||s("AnketaProse",!0),x||s("Whisper",!0),(0,i.jsxs)(c,{children:[(0,i.jsx)(r,{title:"Общая информация",defaultOpen:!0,children:(0,i.jsxs)(d,{children:[(0,i.jsxs)(h,{title:"Имя персонажа [русс|англ]",children:[(0,i.jsx)(n.p,{children:(0,i.jsx)(n.strong,{children:"Линнет-Энн Крофт | Linnet-Ann Croft"})}),(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"Полное имя вряд ли кто-то знает, так как практически с самого начала нежизни грешница отбросила второе имя. Тогда она этого не помнила, но его давали всем девочкам рода Клоуд. Лин это никогда не нравилось, и это чувство отчетливо пробивалось после смерти, что в итоге подтолкнуло к решению."}),"\n",(0,i.jsx)(n.li,{children:"«Лин-Калека» — редкое прозвище, которое могут знать, если им вообще известна личность Лин, взрослые грешники. Совершенно неприятная кличка, от которой грешница закипает внутри. Получена после наказания Сталкера и совершенно правдива, так как Линнет в действительности имеет довольно серьезную травму."}),"\n",(0,i.jsx)(n.li,{children:"«Заноза» — прозвище дано за проблематичный характер членами Рода. Возможно, кому-то за пределами семьи об этом известно."}),"\n"]})]}),(0,i.jsx)(h,{title:"Возраст",children:(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"прожитый в Загробном мире как грешная душа – 80 лет."}),"\n",(0,i.jsx)(n.li,{children:"прожитый на Земле – 36 лет."}),"\n",(0,i.jsx)(n.li,{children:"дата рождения | смерти: 15.04.1902 | 21.07.1938."}),"\n"]})}),(0,i.jsx)(h,{title:"Пол",children:(0,i.jsx)(n.p,{children:"Женский"})}),(0,i.jsx)(h,{title:"Раса",children:(0,i.jsx)(n.p,{children:"Джинн (гуль)"})})]})}),(0,i.jsxs)(r,{title:"Психологический профиль",children:[(0,i.jsx)(r,{title:"Характер",children:(0,i.jsxs)(j,{children:[(0,i.jsxs)(x,{children:[(0,i.jsx)(n.p,{children:"— Смотри, это Миранда Дилхорн. Манекенщица, я тебе про нее рассказывала. Посмотри, как вокруг нее вертится младший Бойнтон, как бы не выскочил из штанов… — немного поодаль от шумной толпы, на вечеринке в Хэмптон-Хаус, Линнет, попивая третий бокал мартини, разговаривала со своей знакомой. Ее нельзя было назвать подругой, о чем Лин предусмотрительно вслух не говорила, но Дороти была выше по статусу, а оттого возможностей у нее было больше. Особенно сплетен о золотой молодежи не только Британии, но и Америки. Дороти как раз рассказывала очередную."}),(0,i.jsx)(n.p,{children:"— При этом делает вид, будто видел ее пару раз, но мне рассказали, что их вместе видели на Ривьере в весьма однозначных отношениях, — первую часть предложения Дороти проговаривала едва ли не на скорость, но со слов «на Ривьере» замедлилась и почти перешла на шепот. Лин же смотрела на указанную парочку: они мило щебетали, та самая Миранда открыто смеялась, слушая какой-то рассказ молодого мужчины рядом. Она была красивой, правда, и даже модное в те времена платье не могло скрыть стройную фигуру, а макияж выгодно подчеркивал мягкие черты лица."}),(0,i.jsx)(n.p,{children:"— Неужели? — с удивлением и нотками пренебрежения спросила тогда еще Клоуд и сделала большой глоток коктейля. Не следовало, но внутри разгоралось пламя зависти, которое нельзя было показать обществу."}),(0,i.jsx)(n.p,{children:"— Ничего особенного, одни кости. Кажется, я слышу, как они гремят при движении, а здесь, между прочим, громкая музыка. Да и смех… такой вульгарный. А что по этому поводу думает его отец? — Линнет подавала всё как можно нейтральнее, и взгляд на пару пыталась смягчить, но это бы получилось, будь она трезвее. Сейчас же девушка, не одаренная ни красотой, ни талантами, готова была проделать дыру во лбу Миранды. На ее месте должна быть Лин. Лин должна была быть и на Ривьере, наслаждаться ресторанами и пляжами в обществе Бойнтона-младшего."}),(0,i.jsx)(n.p,{children:"— Ходят слухи, что отец и не знает. А если и знает, то не придает этому большое значение: она не первая и не последняя. Джеймс женится на той, на которую укажет отец, и это точно не будет какая-то манекенщица, — слова Дороти немного успокоили Лин. В конце концов, жених был завидный: сын маркиза. И партия должна быть подходящей, с хорошей родословной и титулом. Семья Клоуд была в числе тех, кто рассчитывал на состояние Бойнтонов. Но ирония в том, что менее чем через год эта «милая» пара сыграла свадьбу вопреки пересудам и к большому разочарованию Линнет"})]}),(0,i.jsx)(n.p,{children:"Стоит отметить, что важную, если не основную, роль в становлении характера Лин, даже после смерти, сыграло происхождение. Это не оправдание, а факт. Родители, чье положение заметно ухудшилось после Первой Мировой войны, желали не просто вернуть себе прежние блага, но и увеличить их. В не последнюю очередь за счет детей."}),(0,i.jsx)(n.p,{children:"Линнет воспитывали с установкой, что общество жестоко, особенно общество аристократов. Такие люди постоянно сражаются друг с другом за лучшие дары этого мира. В первую очередь – материальные. Конечно, в этой борьбе, как и полагается, делались перерывы на молитвы и церковные службы, но в конечном счете всё возвращалось на круги своя."}),(0,i.jsx)(n.p,{children:"Родители понимали, что посредственная внешность Линнет, о чем, разумеется, ей напоминали, не поможет на ее жизненном пути, а потому вбивали не просто знания, коими и должна располагать леди в современном обществе. Они пытались вылепить харизматичную и остроумную девушку, способную словом перетягивать внимание на себя и управлять им. Пытались выявить таланты хоть к чему-то более-менее значимому. Также, что отец, что мать, обучали искать слабые места людей, развивать наблюдательность, находить такие связи, которые смогут обеспечить нужную информацию. Уязвимости всегда есть, и чтобы больнее уколоть соперника, нужно непременно знать, куда. Не то чтобы они сами были такими или гордились чем-то подобным. Пестовать в себе и детях грехи – Боже Милостивый! Но они не в том положении, чтобы вести истинно Богоугодный образ жизни. И опускаться до уровня простых рабочих, разумеется."}),(0,i.jsx)(n.p,{children:"Но был в их воспитании промах. Такой после которого в душе Лин поселилась и по сей день не отмерла зависть. Родители сравнивали. Постоянно. Всегда был кто-то лучше: лучше выглядел, музицировал, танцевал, запоминал, да что угодно. Может, это поначалу и служило мотивацией стараться, но после стало навязчивой, надоедливой мыслью, с которой, порой, Крофт засыпала и просыпалась. От которой некуда было деваться. И теперь при встрече с кем-либо она оценивала его, нередко ища изъяны уже с первых минут. К сожалению для себя отмечала, что не дотягивает. Увы. От такого понимания Лин, когда не было посторонних глаз, срывалась на тех, кто был однозначно ниже по статусу, например, на прислуге. Но на публике старательно удерживала соответствующей ее положению образ."}),(0,i.jsx)(n.p,{children:"Сейчас Крофт не утруждает себя и не подбирает манеру общения в зависимости от того, с кем ведет диалог. Она отметает вежливость и титулы, не лебезит и не заискивает, предпочитая общаться прямо и нередко грубо. Линнет рассудила, что Энкраж, в конце концов, его правила и опасности потворствуют тому, чтобы не скрывать свое скверное нутро. Недалеко от правды и то, что грешница банально устала от того, что необходимо раз за разом подбирать разные лица и фразы для своих нужд, а ведь это присутствовало и в земной жизни, и в посмертной долгое время. Прямота, однако, не исключает некоторого коварства, недомолвок, двусмысленных фразу и полутонов: в конце концов Линнет – джинн. У них подобное в естестве."}),(0,i.jsx)(n.p,{children:"Будучи смертной Крофт любила перетирать разные слушки и сплетни. Она даже вела записи, чтобы не забыть и распространить в нужный момент, а также нет-нет да и придумывала что-то от себя. Старалась, конечно, отводить подозрения и зачастую притворно возмущалась после того, как рассказывала. Делала вид, что услышала от кого-то другого. И если поначалу не звучала убедительно, то с практикой научилась достоверно врать. И ни разу не испытывала стыда за все это. Родители же наказывали, что в борьбе все средства хороши, на кону стоит большее, чем благополучие других – их собственное процветание. Эту свою любовь Калека перенесла и в посмертную жизнь, также продолжает вести записи и бережно их хранит как можно дальше от любопытных глаз."}),(0,i.jsx)(n.p,{children:"При этом имеет пристрастия к некоторым вещам. К самым разным: одежда, аксессуары, кости или перья зверей, какие-то странные артефакты, особенно если они редкие. Но порядка такие накопления не знают. Ей удобнее находиться и ориентироваться в бардаке. При этом на фоне бедлама сама джинн выглядит, что называется, с иголочки."}),(0,i.jsx)(n.p,{children:"Скверный характер не исключает таких черт Крофт как терпеливость, холодность рассудка и острый, пытливый ум, умение действовать спокойно и быстро, особенно в критических ситуациях. Иначе бы Лин уже давно лишилась ядра. Тем не менее, «благодаря» своему подходу ко всему через прямоту и невежество имеет мало тормозов, из-за чего нередко попадает в неприятности. Из-за слепящего желания доказать кому-то свою значимость и силу Линнет упрямится, ругается, прыгает выше головы и непременно ее разбивает. Результат, как минимум, неприятная кличка, взявшаяся не из пустого места и вполне отражающая реальность Линнет. Удивительно, что с таким языком она вообще до сих пор существует, да еще и более-менее дела ведет."}),(0,i.jsx)(n.p,{children:"Не испытывает мук совести за свои слова, мысли и поступки. Мораль переоценена, собственная шкура и ее достойный вид куда важнее. Может, разве что, сокрушаться над тем, что сделала недостаточно для собственного блага, ненавидеть и мысленно лупить себя по щекам."}),(0,i.jsx)(n.p,{children:"Ценит уединение и возможность оставаться в одиночестве как можно больше времени. Среди своего «злата» спокойнее, особенно когда нет раздражающей суеты вокруг. В связи с этим Крофт даже названия своей лавке не дала – для большей неприметности."}),(0,i.jsx)(n.p,{children:"Но вместе с тем тянется, в некотором роде, к диалогу, неосознанно желает быть выбранной, хотя бы, для начала, как собеседник, даже такой скверный. А еще для Лин этот выбор может значить то, что она все же лучше конкурентов. Вот и получается, что с одной стороны она, уставшая от общества, в котором ее главный грех только множится и причиняет страдания, тяготеет к нему и занимается самообманом."}),(0,i.jsx)(n.p,{children:"Так уж вышло, что Крофт любит свое маленькое дело и горда тем, что достигла определенных результатов. Забавно, что в каком-то смысле она и стала той самой прислугой, которую нередко дергала и презирала за статус. Работа грязная во всех смыслах, да еще и эта неизлечимая зависимость от энергии, за которую и приходится лезть в пасть зверю. Иногда в прямом смысле. Но она, черт побери, при всем вышеперечисленном, приносит какое-то облегчение, позволяет выпустить пар, да и знаний набраться. А это важно, в конце концов. Плюсов выходит куда больше."}),(0,i.jsx)(n.p,{children:"Из-за того, что, в силу травмы, не может полагаться на свое тело, научилась быть хитрой и изворотливой, добиваться нужного результата разными способами. Её хитрость, стоит отметить, происходит не из того, что ей это нравится. Её хитрость не обладает каким-то кокетством и заигрываниями. Лин не испытывает какого-то особого удовольствия, если прибегает к такого рода уловкам. Просто способ, просто необходимость."}),(0,i.jsx)(n.p,{children:"Не любит быть должной, как и не плодит список должников, хоть и имеет таковой. Поди найди их потом. А вдруг помрут раньше времени? Нет, уж лучше пусть сразу платят по счетам."}),(0,i.jsx)(n.p,{children:"Увязнув в зависти, Лин в некотором роде отпустила другие грехи. Например, ей мало знаком гнев в чистом виде. Если он присутствует, что правда, то непременно тлеет и отравляет глубоко внутри и редко демонстрируется. Либо же преображается в что-то другое: да, злобное и агрессивное, но, если можно так сказать, исторгается подколками, подтруниванием и оскорблением. Но не является самоцелью. Как и алчность, похоть, гордыня и так далее. Стоит понимать, что Крофт подвержена влиянию всех грехов, как и всякий, просто источником остальных, чаще всего, является именно зависть."}),(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Зависть."})," Этот грех мелькает на разных этапах описания личности Линнет, но до сих пор не раскрыт в полной мере. Пожалуй, самое время."]}),(0,i.jsx)(n.p,{children:"Зависть – топливо. Зависть порождает амбиции, целеустремленность, упорство, желание достигать большего, чем дано изначально, но также тянет за собой бесконечные сравнения, ненависть и желание не просто казаться лучше, а быть. Иметь едва ли не исключительные таланты, силу, влияние, вещи. Список можно долго продолжать. Суть остается одна – Лин невыносима мысль о том, что она так и осталась серостью. Бледной тенью, на фоне которой остальные кажутся более яркими и заметными. Некрасива, бездарна, бесполезна. Крофт знала, что говорят о ней там, на вечерах с ослепительным светом, искристыми напитками и боа из перьев. Знала и рыдала в подушку, неспособная исправить. Как бы не старалась, всегда оставалась позади, все с теми же сплетнями, прожигающим исподтишка взглядом и попытками продолжать борьбу, навязанную родителями за место под тусклым солнцем Туманного Альбиона. В Энкраже, прежде всего, грешница отстаивает собственные интересы и желания и давно забыла о том, как лить слезы. Но не жалеть себя."}),(0,i.jsx)(n.p,{children:"Временами впадает в меланхолию, теряя уверенность в своих силах и в правильности совей жизни. том, что все стены, которые Крофт старательно возводила, были необязательны. Что родители были неправы, что в мире, любом, есть что-то реальное хорошее и светлое, которое доступно каждому, даже такой черствой душе. Но тогда все уклады вмиг рухнут, оставив за собой такое разочарование, которое разом пожрет все существо Линнет, оставив лишь оболочку. Когда живешь в одних убеждениях так долго, очень страшно даже помыслить альтернативно. Поэтому она всегда сама всё рушит, не стремясь к искуплению и покаянию. Кстати, давно легко определить, когда Линнет отдает себя на растерзание унынию. Она грубит куда меньше, чем обычно. Одиночество в такие моменты перестает быть приятным и становится тисками."}),(0,i.jsx)(n.p,{children:"А что же в итоге получается? Да ничего хорошего. С таким характером Лин непременно ждет еще одна могила. Просто удивительным образом вышло так, что копает ее грешница слишком долго. Хотя одной ногой она уже там."})]})}),(0,i.jsx)(r,{title:"Страхи",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Страх повторного наказания",children:(0,i.jsx)(n.p,{children:"Джинн можно назвать смелой, однако есть ряд вещей, которые вводят либо в ступор, либо в панику. Одним из таких является Сталкер, который, когда явится, то не для того, чтобы забрать травму, которую сам же нанес. Скорее он добавит еще чего, чтобы ухудшить положение Крофт. Это способно остановить ее действия и поступки, развернуться, сдаться и запереться ото всех в страхе получить аудиенцию с палачом."})}),(0,i.jsx)(h,{title:"Страх не вернуть дееспособность",children:(0,i.jsx)(n.p,{children:"Страх никогда не вернуть себе полную дееспособность и прежнюю привлекательность. Эта тема способна вывезти Лин из себя так, что она перестанет трезво оценивать свои способности и положение. В противовес предыдущему страху она может совершить необдуманные поступки в надежде больше никогда не испытывать мук боли и терпеть насмешки других."})}),(0,i.jsx)(h,{title:"Страх не достичь значимых результатов",children:(0,i.jsx)(n.p,{children:"Страх не достичь значимых результатов, оказаться в том же положении, что и при жизни. Иначе все старания, все это копание в грязи и дерьме ничего не значат."})}),(0,i.jsx)(h,{title:"Характер",children:(0,i.jsx)(n.p,{children:"Как бы это не звучало, но ершистый характер, несмотря на амбиции, мешает в жизни не хуже травмы, где-то замедляет или вовсе лишает желаемого результата."})}),(0,i.jsx)(h,{title:"Отсутствие иммунитета к магии",children:(0,i.jsx)(n.p,{children:"Отсутствие особенного иммунитета к любого вида магии. Особенно Лин старательно избегает тех, кто может воздействовать на разум как напрямую, так и косвенно."})})]})}),(0,i.jsx)(r,{title:"Мечты, цели",children:(0,i.jsxs)(j,{children:[(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Вернуть себе полное здоровье и подвижность."})," Мысль о том, что это ей не удастся, не допускается. Линнет ищет способ исцелить травму, нанесённую Сталкером."]}),(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Обрести полную независимость от чужой энергии."})," Но при этом оставить возможность её черпать. Лин стремится избавиться от зависимости, которая унижает её и ставит в положение просительницы."]}),(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"Не достичь значимых результатов."})," Она боится оказаться в том же положении, что и при жизни — серостью, которой никто не замечает. Поэтому её цель — стать значимой, сильной, превзойти тех, кто её окружает."]})]})}),(0,i.jsx)(r,{title:"Биография (при жизни)",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(n.p,{children:"Линнет-Энн Крофт родилась, можно сказать, с серебряной ложкой во рту. Ее семья была не просто состоятельна, но обладала титулом, который в те времена имел вес. Виконт Клоуд, из старой английской аристократии, обладал несколькими источниками дохода: сельское хозяйство, винокурня, несколько домов, которые сдавались в аренду. И пусть он не расширил способы увеличить капитал, хоть и пытался, но, по крайней мере, до начала Первой Мировой войны крепко удерживал активы."}),(0,i.jsx)(n.p,{children:"Линнет была средней дочерью, между двумя братьями. Разумеется, мальчики получали больше внимания со стороны родителей, в особенности старший, как наследник. Но и нельзя сказать, что о Лин забывали. Не в том сословии она родилась."}),(0,i.jsx)(n.p,{children:"Довольно быстро родители поняли, что Лин растет не очень приметной внешне и не очень способной. В чем-то даже отталкивающей. Это могло создавать определенные трудности в дальнейшем, а потому было приято решение усилить обучение Энн. Её удел, прежде всего – удачное замужество и достойное представление семьи в обществе. Кто знает, насколько на выбор Лин в качестве невесты повлияет состояние виконта."}),(0,i.jsx)(n.p,{children:"В целом, родители воспитывали детей с некоторой долей цинизма, игнорируя их чувства и не проявляя лишний раз мягкости. Они считали, что было, в общем-то, правдой, что высшее общество жестоко. Оно пьет кровь вместо чая и не видит слез. Не замечает, как топчет и забивает слабых духом, отбирая все."}),(0,i.jsx)(n.p,{children:"В 11 лет, после плотного домашнего обучения с посредственными результатами Линнет отправили в Челтнемский женский колледж, и это решение было одним из лучших, вполне окупало высокую цену за обучение. Тем не менее, больших талантов Энн не удалось раскрыть. Возможно, виной тому была Первая Мировая Война."}),(0,i.jsx)(n.p,{children:"Великобритания отдала этой войне многих, порядочно обескровив аристократов. Вряд ли можно было найти семью, которую не коснулись последствия боевых действий. Так, старший брат Лин, отправившийся на фронт добровольцем, не вернулся домой, а отец был серьезно ранен и едва смог оправиться. Потеря наследника, во всех смыслах отличного сына, способного, с хорошей личной репутацией, на которого возлагались большие надежды, тяжело сказалась на семье. Шарлотта, мать Лин, долго носила траур, а иногда впадала в такие состояния, что видела в младшем сыне старшего и обращалась к тому соответственно."}),(0,i.jsx)(n.p,{children:"Сама же Энн в первые два года войны оставалась в колледже, который стал базой Красного Креста, где помогала в госпитале. Впоследствии Линнет старалась никогда не вспоминать тот период. Не вспоминать искаженные болью и ранами лица солдат, не думать об их стонах и криках в бреду, не видеть, закрывая глаза, как жизнь покидает тела людские. Не вспоминать о том, как много плакала первое время. Эти образы не сильно притупились с течением лет. Особенно не выходил из головы Крофт молодой парень, один из многих, за которым она ухаживала. Он хотел вернуться домой к возлюбленной, с теплом глядел на ее фото, потрепанное, но бережно хранимое. Он рассказывал о том, как непременно на ней женится, как назовет детей, какие чудные у любимой ямочки на щеках, когда та улыбается. Он плакал, кричал ее имя, охваченный лихорадкой, а перед самой смертью, бредя и уже не веря в поправку, просил Линнет найти ту девушку, и рассказать, как сильно солдат ее любит. Парень скончался, проиграв смерти, а Энн, естественно, не дав обещания, его же и не выполнила. Почему-то, потом, сама находясь при смерти, Крофт в деталях вспомнит лицо того солдата."}),(0,i.jsx)(n.p,{children:"Но эти события будут позже. А пока что молодая девушка в 1917 году возвращается домой. Из скорби в скорбь. От войны к «испанке», которую чудом удалось миновать."}),(0,i.jsx)(n.p,{children:"Но не только смерть наследника поразила Клоудов. Их материальное положение сильно просело во времена войны и пандемии. Не только о колледже, пришлось забыть о винокурне. Некому было сдавать в аренду землю для сельскохозяйственных угодий."}),(0,i.jsx)(n.p,{children:"Разумеется, глава семейства не желал мириться с таким положением. И на Лин было обращено куда большее внимание, а вопрос с удачным замужеством стал острее. Не то чтобы она была против. Наоборот, очень даже за. Только вот ей с самого детства вбивали в голову мысль, что Энн недостаточно хороша, что нужно стремиться к лучшему. Если не получается одно, то нужно переключиться на другое. И так раз за разом."}),(0,i.jsx)(n.p,{children:"Была в их наставлениях и польза, безусловно. Так, Лин развивала наблюдательность, старательно подсматривала за другими, собирала о них сведения. Любая информация может стать полезной. Впоследствии это отразилось и на жизни Крофт в Энкраже и положительно на ней сказалось. Вместе с тем, такая тактика имела и минусы в виде греха зависти, который рос и питался мыслями Линнет. С кем-то война обошлась мягче как минимум, кто-то смог быстро подняться после всех горестей и так далее, далее, далее. Чем дальше, тем хуже."}),(0,i.jsx)(n.p,{children:"Пожалуй, можно сказать, что Первая Мировая Война переломила старушку Англию. Но «подарила» ревущие 20-е. Как стремительно менялся мир вокруг: мода, музыка, политика. А какие вечеринки закатывала золотая молодежь в своем стремлении забыться, не помнить о тяготах, причиненных войной. Это время Лин вспоминала с куда большим удовольствием. Пусть наблюдение за чужой радостью и успехами болезненным, тяжелым отпечатком ложилось на душу Крофт, веселье было заразительным. Она с удовольствием пользовалась вольностями, подаренными женщинам в те годы. Модные прически, платья с прямым силуэтом, курение, яркий макияж – хотелось попробовать все, и к черту старые порядки. И пусть внешность Линнет вполне могла сойти за эталонную, всё современное смотрелось не очень. Неорганично и топорно. Семья из кожи вон лезла, чтобы соответствовать новым стандартам, ведь стоили они недешево, но сталкивалась с, так сказать, провалами."}),(0,i.jsx)(n.p,{children:"Подумать только, Крофт хотела устроиться на работу! Она, которая приказывает, а не прислуживает, только бы быть на нее обратили внимание, отметили старания и стремления. Но, не обладавшая, как уже было сказано ранее, талантами, ничего не вышло. Ни фотография, ни писательство. Картины и вовсе были ужасны. Конечно, Линнет не сдавалась и была уверена в том, что найдет свое призвание, что не бездарна. Таланты у нее есть, нельзя даже в этом сомневаться. Но со временем попыток стало меньше. Зато больше вечеринок, на которых можно было попробовать всякое. Впоследствии это всякое выросло в зависимость, ставшую фатальной."}),(0,i.jsx)(n.p,{children:"Вышла замуж Линнет довольно поздно по тем временам – в 30 лет. За кузена по материнской линии – так Клоуды пытались сохранить хоть сто-то от их прежнего состояния, а заодно пристроить, наконец, дочь, которая так и не нашла «достойную» партию. Крофты, положение которых было куда лучше, согласились, так как, в каком-то смысле, сами не имели выбора. Младший сын, Дэвид, не снискал большой славы ни на войне, ни в светском обществе, не влюбил в себя долларовых принцесс Америки. Пусть нравы общества стали куда более вольными, некоторые вещи вроде брака, особенно в среде аристократов, были неизменными."}),(0,i.jsx)(n.p,{children:"Великой любви, конечно, не случилось. Точнее сказать, вообще никакой: супруги друг друга попросту терпели, редко разделяя между собой вечера, не были друг другу верны, особенно Дэвид. А иногда и терпения не хватало. Им бы развестись и разойтись по сторонам, но воля родителей была сильнее. К тому же, сама Лин была против. Пусть это был гнилой, но фасад. Пусть все всё и так знали, но развод стал бы лично для нее ударом, очередным провалом. А они всё множились, как и зависть. Ее не утопить уже в алкоголе, не заесть, а потому в ход пошли наркотики."}),(0,i.jsx)(n.p,{children:"А дальше – смерть. Дэвид умудрился встретить ту, кто и впрямь полюбил ее. Ему не оставалось никакого смысла держаться за брак с Линнет, которая лишь глубже погрязала в своих грехах и скверных мыслях. Она не любила мужа, так все и осталось, но брак сам по себе был важен, она убедила себя в этом. Развод сделает только хуже, Лин совсем никому не будет нужна, особенно с опасными зависимостями. Это станет позором. Общество не просто будет шептаться – оно заговорит. Так Линнет думала. Оно заговорит, а Крофт не выдержит. Очередное осознание какой-то никчемности, бессилия, невозможности кого-то превзойти. Очень много было скверных мыслей в тот вечер, когда супруг заявил о разводе. Желая хоть немного заглушить этот хоровод, хоть немного выскользнуть от неудачной реальности, Лин приняла много морфия и добавила к нему алкоголь. Организм попросту не выдержал. Крофт умерла в агонии, в собственной рвоте. Никто не пришел на помощь, потому что она даже позвать не смогла."})]})}),(0,i.jsx)(r,{title:"Жизнь в Энкраже",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(n.p,{children:"По сей день Линнет смазано помнит Башню и ее испытания. Разум подбрасывает, скорее, статичные картинки и притупленные ощущения. Грешница, разве что, отчетливо помнит собственное упрямство и доказать, в первую очередь, себе, что пройдет всё. И все же странно то было. Когда не осознаешь своей личности, не имеешь прошлого, но от тебя уже что-то требуется. Не знаешь ни цену ошибки, ни выигрыша. Не понимаешь, откуда берется желание, во что бы то ни стало, пройти проклятые испытания, почему создаешь такую внешность. Странное чувство наполнение, когда дух обретает плоть, как перестраивает сам себя. Зачем всё это, и что делать дальше? Неясность злила и пугала одновременно."}),(0,i.jsx)(n.p,{children:"А затем был Замок. Лин он не казался располагающим к себе. Ни безопасным, ни комфортным, но хотя бы понятным внешне. Он взирал на нее высокими стенами, холодными и неприступными, не торопился пригласить на экскурсию. Но подоспевшие вскоре после появления Лин реальты внесли ясность и помогли новой грешнице немного осознать свое положение. Крофт не была робкой и застенчивой, но затихла, чтобы наблюдать. Обратилась в слух, чтобы не упустить ничего из того, что ей расскажут. Засыпала вопросами. Не понимала ответов, но не останавливалась."}),(0,i.jsx)(n.p,{children:"Прежде чем искать своих, а это, так или иначе, было необходимо, Крофт остановилась в общежитии, чтобы хорошенько обдумать свое положение. Свыкнуться, постараться принять, немного понять. Ей, конечно, не нравилось делить комнату еще с кем-то. Отголоски прошлого, о котором девушка не ведала, вселяли уверенность, что ей нужны куда лучшие условия. Мог бы кто-то предположить, во что в итоге это выльется, и как быстро выветрится этот дух аристократизма?"}),(0,i.jsx)(n.p,{children:"В общежитии пришлось задержаться: Лин решила прощупывать новый мир последовательно, не влезать в неизведанные, сомнительные дела, и лучшим решением было обосноваться в библиотеке. Самообучение, конечно, замедляло, в некотором смысле, но уже в первые годы после смерти Лин не стремилась к обществу. Исключением было время сразу после попадания в замок: джинн получила поверхностные инструкции, и уже отталкивалась от них. Первым делом она изучала собственную расу, параллельно пытаясь ответить на вопрос, почему именно они. Да, была Башня, но без знания собственного прошлого, своих действий, мыслей, осознание выходило неважным. Крофт не страшилась узнать о себе: наоборот, считала, что понимание своей личности поможет ей освоиться. Однако воспоминания не торопились возвращаться: приходилось чаще чем обычно прислушиваться к себе, к тому, как она относится к той или иной информации."}),(0,i.jsx)(n.p,{children:"Довольно быстро Крофт поймала себя на мысли, что, несмотря на нелюдимость, она склонна оценивать других как бы со стороны. Смотреть за ними, наблюдать, а при упоминании каких-то именитых личностей, с оговоркой об именитости, разумеется, искала, по возможности, о них сведения. И понимала, что испытывает зависть, причем это начиналось с мелочей: одежды, манер, способностей, расы, а уж потом доходило до положения в местном обществе и влияния. Ей хотелось так же. Просто обладать этим, не обязательно кичиться. Знать, что Лин может не просто не хуже, а даже лучше. Что она имеет право иметь. И не просто что-то, не ограничиваться необходимой базой, а знать, что можно свободно распоряжаться, растрачивать, не думая о том, как сложно будет потом."}),(0,i.jsx)(n.p,{children:"Она действительно просиживала часы в библиотеке, пытаясь не просто прочитать и запомнить, но как-то структурировать, прикинуть, где и в какой момент это может пригодиться и может ли вообще. И это была та еще пытка! Дело даже не сколько в энергетическом голоде, сколько в болезненном восприятии света. Глаза слезились, ощущалась резь, много времени нужно было потратить хотя бы на то, чтобы настроить освещение так, чтобы страниц книг были читаемы, но без особого вреда глазам."}),(0,i.jsx)(n.p,{children:"Но и вышеупомянутый голод никуда не девался. О, как же он раздражал! О нем нельзя было забыть надолго, занять себя чем-то так, чтобы не думать. То были странные ощущения, непривычные. Физический голод был понятен на подсознательном уровне, вполне просто удовлетворялся, но это… Усталость, раздражительность, мутность, даже сложно подобрать описание. И это очень раздражало. Почему гуль, почему джинн?! Что такого в смертной жизни сделала Линнет, чтобы получить такие испытания? Ей совершенно не прельщали контракты по своей сути. Этакая перманентная зависимость сверх остальных. Ей совершенно не хотелось напрямую зависеть от кого бы то ни было. Но реальность диктовала свои условия, и опустошение и энергетический голод толкали Крофт на путь контрактов. Но что может предложить юный джинн? При условии, что в общем эта раса старается не распространяться о себе и правильно делает? Вопрос риторический. Линнет помнит те времена особенно, через призму бесконечного унижения, когда за «гроши» нужно было братья за опасные для себя дела без толкового знания о мире и порядках. Упорство, желание не просто жить, а преодолеть все это, доказать себе и всем свою силу, помогало Лин «получать свое»."}),(0,i.jsx)(n.p,{children:"Долго такой порядок вещей не длился: не уверенная в том, что знает достаточно, Крофт двигается дальше в поисках своих. Ей удалось разузнать, что она возможно найдет джиннов на базаре."}),(0,i.jsx)(n.p,{children:"Так и случилось, но встреча с родом произошла не сразу. По своему уже сложившемуся обычаю Крофт наблюдала. Сначала то было скитание по базару с целью понять его. Кто чем торгует, как, о чем болтают. Пару раз даже сама подходила к прилавкам, соизволив завести ничего не значащий разговор. Но долго так было нельзя, ведь она и сама примелькалась местным. Мало ли что унюхать пытается. Новые лица очень быстро замечаются. И когда ее спросили напрямую, что вынюхивает, Крофт не нашла что ответить. Стушевалась, не выдумав достойную легенду. Тогда она позорно сбежала, наверняка навесив на себя больше подозрений."}),(0,i.jsx)(n.p,{children:"Затем, собравшись с мыслями, перешла к настойчивым и не очень вежливым расспросам. Подстегивал и растущий голод. Либо она найдет своих, либо вернется обратно, в унижение."}),(0,i.jsx)(n.p,{children:"Как уже было сказано, новые лица на старом месте очень заметны. К Линнет тоже присматривались. Оценивали. Уже знали, кто она. Вопрос был лишь в том, достойна ли? Хотя, честно говоря, этот вопрос стоял не столь остро, но об этом чуть позже."}),(0,i.jsx)(n.p,{children:"Род восточноевропейских джиннов Корвин был основан венгерским дворянином с по его же фамилии много столетий назад, и много на своем веку успел повидать. Еще совсем недавно, по меркам Энкража, с этой семьей нужно было считаться, их состав и мощь были внушительными. Но на заре 20 века от этого мало что осталось. Разве что былые заслуги, на которых особо не удержаться. Из примечательного, помимо богатой истории, в достаточно закрытую семью принимались лишь грешники, происходившие из стран Восточной Европы. Данное правило практически не изменилось в нынешние времена: среди Корвин можно было найти детей из других, но исключительно европейских стран. Никакой Америки, никакой Азии и так далее."}),(0,i.jsx)(n.p,{children:"После определенных событий, как вскользь было сказано, Род был заметно прорежен. Чтобы остаться, что называется, на плаву, Корвин искали новых «детей». В этом смысле Лин повезло."}),(0,i.jsx)(n.p,{children:"Забавная превратность судьбы: и в жизни, и в смерти, Крофт пребывала в обстоятельствах, которые требовали от нее действий, которые бы улучшили положение семьи. Да и общество в Иркалле не то чтобы было мягче. Разве что в этот раз Лин решила держаться иной тактики."}),(0,i.jsx)(n.p,{children:"Итак. Ее приняли, в том числе, за упертость и жажду добиться своего. Они видели, как юная грешница их расы день за днем обретается у торговых лавок, как и какие вопросы задает. Заноза никогда не спрашивала, заняла ли чье-то место, был ли еще кандидат. Ей, в общем-то, было наплевать. Не хотелось терять шансов."}),(0,i.jsx)(n.p,{children:"Конечно, клеймо молодого грешника жгло душу. Это касалось и возможностей, и иерархии. Вокруг нее действительно собрались остатки некогда могущественной семьи. Они были снисходительны, с легкой скукой поигрывали силой и знаниями, маячили этим перед лицом Крофт, прекрасно отдавая себе отчет в том, какой огонь зависти разжигают. Сами через подобное проходили. Аргумент был прекрасный: мотивация идти дальше. И она снова сработала, но результат вышел куда лучше, чем в прошлый раз."}),(0,i.jsx)(n.p,{children:"Довольно быстро Линнет попала на поруки к наставнику. Имре Корвин был едва ли не среди первых в семье. Утративший волю к жизни, этот гуль существовал, скорее, по привычке. Так долго принадлежал в семье, что жить за ее пределами не имела вообще никакого смысла. Ему давно за 500, условия контракта с Хранителем не исполнены, и Имре не был уверен в том, что сможет."}),(0,i.jsx)(n.p,{children:"Первая полноценная беседа между учителем и учеником вышла странной. Мужчина не поздоровался, не завел диалог с стандартных и бессмысленных вопросов, лишь бы наладить контакт. Он «с порога», покуривая трубку, даже не глядя в сторону Крофт, рассказал о ней то, чего она сама о себе еще не знала. Обстоятельства смерти, грехи, какие-то отрывки прошлой жизни, связанные непосредственно с грехами. Линнет стало не по себе. Не ожидала она сведений о прошлом вот так. Не была готова. Имре при этом говорил спокойно, с толикой того безразличия, с которым рассказывают какую-то информацию в тысячный раз. Ему глубоко не интересны слова, срывающиеся из уст. И несмотря на явное замешательство, Крофт такое пренебрежение к ней не понравилось. Она довольно близко к сердцу приняла такое к себе отношение, не предполагая, что наставник одинаков со всеми. Ей стало завидно, стало прогоркло. Какая-то часть из прошлого, когда Линнет отрицала свою никчемность, хотя вполне о ней догадывалась, добавила горчинки. Тем не менее, Крофт не сбежала, а принялась едва ли не тараном переть на Имре. Вопросами и возмущениями. В ответ была стена безразличия. И тем не менее, от нее никто не отказался, а контракт был заключен."}),(0,i.jsx)(n.p,{children:"Учитель продолжал неторопливо обучать, хотя казалось, отрабатывал повинность. Порой вытащить из него какую-то информацию было едва ли возможно, и Лин из-за этого первое время закипала. Ей хотелось получить все как можно быстрее, и всё для чего? Чтобы стать лучше. Значимее. Превзойти. Линнет безумно завидовала наставнику. То, как он легко обращается с силой, как безошибочно угадывает, считывает других. Имре частенько, когда выпадала его очередь стоять за прилавком, разглядывал мимо проходящих грешников. Самыми интересными были новички, но и к старикам мужчина присматривался: вдруг у тех что-то изменилось? Он рассказывал об их существовании через смерти, через суть, при этом визуально никак не напрягался. Просто покуривал трубку, выпускал изо рта сладковатый дымок и рассказывал. Периодически задавал загадки, будто Лин была с ним на одной волне. А та всё не понимала. Аристократические замашки так и проскальзывали в поведении грешницы, капризность и нетерпеливость мешала разумно мыслить. Не сразу Крофт осознала, что ее прошлое, помнит она его или нет, не имеет никакого значения. Да будь она королевой в мире смертных, политиком, шепот которого будет громче тысячи криков – в Энкраже это пыль, которую можно даже не заметить, если не пожелаешь."}),(0,i.jsx)(n.p,{children:"Стоило хотя бы немного принять эту данность и немного присмотреться к наставнику, понаблюдать уже за ним чуть более осмысленно и спокойно, как дело сдвинулось с мертвой точки. Лин заметила, что не вся информация к Имре шла через способности. Некоторые вещи старый гуль подмечал просто по внешнему виду. Он был наблюдательным, и развил этот навык куда сильнее, чем Крофт могла себе вообразить даже при жизни. Линнет постаралась осадить себя, успокоиться. И принять, наконец, методы этого непонятного грешника. Кроме того, такой подход казался смутно знакомым."}),(0,i.jsx)(n.p,{children:"Обучение длилось не один десяток лет. Крофт буквально училась быть джинном. Понимать свои потребности, градации голода, способы его утолить, принципы работы контрактов, последствия. Ее учили понимать флору и фауну Энкража, взаимодействовать с ней через охоту, собирательство, наблюдение. Ресурсы необходимы для торговли, как в привычном понимании, так и в рамках контрактов. Учили разными способами себя защищать. Ей вдалбливали всё ту же истину: мир только кажется другим. Она также жесток и слеп. Он не принесет тебе ничего просто по желанию, так не бывает. Желаемое нужно добывать, уметь это делать. И, самое главное, этот непростой путь и сделает Лин лучше, поможет ей. «Если не хочешь гнить от зависти – используй ее как топливо для движения вверх». Так поговаривал наставник. Лин же каждый раз мысленно дополняла «Верх не имеет границ». Однажды она осмелилась произнести это вслух, и получила в ответ предупреждение. Зря Линнет не послушала."}),(0,i.jsx)(n.p,{children:"Воспоминания грешница возвращала неохотно, но не отказывалась от них. Она решила, что в стремлении «возвыситься» этот вариант тоже окажется полезным. В конце концов, в смертной жизни Лин обучалась, получала навыки. Возможно, осваивала полезные профессии. Где-то помогал Имре, где-то – Башня. Собрав свою смертную жизнь по кускам, Крофт пожалела себя. Она так старалась, и всё скатывалось в бездарную, деструктивную трату времени, которая вообще ни к чему не привела. Как бы неприятные не были воспоминания, но они также послужили мотивацией стараться усерднее."}),(0,i.jsx)(n.p,{children:"С семьей она оставалась на протяжении почти всей своей жизни в Энкраже. И не заметила, как прониклась чувствами к Имре. Это нельзя назвать обычным любовным интересом, но что-то сильно больше, что не сожмешь до одного слова или чувства. Этот грешник, желая того или нет, буквально поставил Лин на ноги. Многому научил. Некоторые способности грешница переняла, в том или ином виде, у него. Он подсказал, как стать еще более значимой, в первую очередь, в собственных глазах. Крофт, стоило той окрепнуть, вовсю демонстрировала дурной характер, злословила и торопилась нахватать проблем, но не с ним. И это при том, что наставник напрямую не отчитывал в прямом смысле, не проявлял бурных эмоций."}),(0,i.jsx)(n.p,{children:"Крофт догадывалась, что ее особое отношение односторонне, но ни на что не претендовала. Ей и так было вполне комфортно. Рядом с ним не хотелось злословить и препираться, приятно было сосредоточиться на работе. Знания шли легко и приятно, практика давалась легче. Лин нравилось наблюдать за тем, как Имре выращивает табак, как старательно он это делает, какой порядок и скрупулёзность соблюдает. Как иногда, забываясь, рассказывает о своем опыте, ощущениях, желании найти что-то новенькое. Он повторялся, но Крофт никогда не подмечала это, слушая, как в первый раз."}),(0,i.jsx)(n.p,{children:"Но те славные дни остались далеко позади. Имре исчез. Никто не знал, когда и куда он ушел. Наставник не оставил записки, не дал инструкций. Словно растворился в воздухе. Сильнее всего случившееся ударило по Лин. И вся та своеобразная покорность, подавление нрава перестали иметь смысл. Они накрыли собой всякое здравомыслие Крофт. Она утратила связь, которая, как казалось, делала ее полноценной. Ее выдрали с корнем, не оставив ничего. Всем своим существом Заноза отрицала самое страшное, но оно произошло: Имре, по всей видимости, был мертв. Стерт из Энкража полностью, если быть точнее."}),(0,i.jsx)(n.p,{children:"Пусть Лин и держалась особняком даже внутри семьи, она и к ним привыкла, в каком-то смысле прикипела. Узнала их лучше, как и они ее. Пусть и не достигли полного взаимопонимания и крепкой социальной связи, но были далеко не врагами, а, скорее, неплохими товарищами. Да, Линнет была Занозой, но их Занозой. Теперь же, согласно правилам, Крофт лишилась и Рода. Имени. Привычного уклада и какой никакой стабильности. В одночасье Лин вернулась в начало своего пути."}),(0,i.jsx)(n.p,{children:"Правда в этот раз гуль не была неоперившимся птенцом. У нее были знания, сила, и движущая жажда отомстить, высвободить всё, что подавлялось годами и навалилось вследствие горя от новости о смерти наставника. Некому ее останавливать, некому образумить и помочь свернуть с намеченного пути. В течение нескольких лет Крофт носом землю рыла в поисках убийцы. Имре был закрытым для всех, и сведения о его контрактных обязательствах зачастую оставались при нем. Но упорство и не утихающая жажда толкали вперед. При этом она не забывала обучаться чему-то новому. Привычка, неугасающий интерес. В отличие от земной жизни здесь все получалось как-то лучше. Не то чтобы легче шло, отнюдь. Линнет не раз находилась в опасности или подвергала ею близких, не всегда быстро соображала и ошибалась. Просто горизонты здесь были куда более привлекательными, и результат ощущается куда лучше и очевиднее."}),(0,i.jsx)(n.p,{children:"Причина, по которой Имре погиб, была стара как этот мир. Джинны, и их загадочная, манящая сила. Особенно для оммёдзи. Один из таких, подгоняемой жаждой постичь природу магии в разных ее проявлениях, «вскрыть» нутро джиннов не принял отказа и неподчинения. Сложно сказать, как ему удалось одолеть старого и довольно сильного грешника, потому что впоследствии Лин убила его. Что же было на уме у наставника в те минуты? Иногда Линнет задает себе этот вопрос, но ответить на него некому."}),(0,i.jsx)(n.p,{children:"Крофт вполне осознавала последствия своего поступка и не пускалась в бега, когда тыльную сторону ладони обожгла метка. И тем не менее, она не была готова к наказанию. Как и все, гуль смутно помнила о том, что же с ней сделал Сталкер, но некоторые эпизоды, связанные с истязаниями, болезненно врезались в рассудок грешницы. При одном только упоминании этого существа в диалоге или мысленно пытки ощущаются в моменте также ярко, как и 5 лет назад. Становится по-настоящему страшно. Крофт в настоящее время старается не навлекать на себя луч внимания Сталкера, но ее природу не изменишь. Как долго продлится такое «смирение»? Год? Два?"}),(0,i.jsx)(n.p,{children:"Линнет сполна ответила за свое преступление, и осталась на неопределенное время хромой. С болью в ноге, от которой периодами хочется кричать, с изуродованным лицом и осознанием своей ограниченности, от которой стремилась убежать. Мысль о том, что Имре отомщен, грела душу, но не притупляла боль. Что делать дальше Крофт не знала. Решила, что будет делать то, что умеет: торговать. Уже позднее, когда более менее пришла в себя, и смогла, при очередном болезненном шаге, не думать о Сталкере, задалась целями, одной из которых было исцеление."}),(0,i.jsx)(n.p,{children:"По старым связям и мимолетным контрактам ей удалось обосноваться на всё том же Базаре. С чего начинала, к тому и пришла. Последние пару лет Крофт владеет торговой лавкой без названия и кричащей рекламы. Там и работает большую часть времени, и живет."})]})})]}),(0,i.jsxs)(r,{title:"Дополнительно",children:[(0,i.jsx)(r,{title:"Факты о персонаже",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Коллекционирование очков и тростей",children:(0,i.jsx)(n.p,{children:"Усиленно коллекционирует очки и трости, активно использует их в повседневности. Трость так вообще по прямому назначению. Даже если одежда будет одна и та же продолжительное время – указанные аксессуары будут другими. Лин тянет их из верхнего мира, заказывает у местных мастеров, указывает в качестве оплаты своих услуг. Сильные артефакты порой не имеют такой ценности для грешницы как старая, потрепанная временем, трость. Ставит себе целью заказать на изготовление такую, чтобы принимала облик любой трости из личной коллекции Крофт, и была, к тому же, очень прочной. А также – отыскать того, кто смог бы сохранять целостность предметов из верхнего мира."})}),(0,i.jsx)(h,{title:"Табак и сигареты",children:(0,i.jsx)(n.p,{children:"Сама взращивает «табак» и делает сигареты, все необходимое у Линнет, как правило, есть. Иногда, для разнообразия, тянет табак, бумагу или цельные сигареты из верхнего мира, пользуясь ключами. Как-то раз упрямо пыталась из семян верхнего мира вырастить табак в Энкраже. Результат представлять не нужно. Постоянно носит с собой маленькую пепельницу и портсигар, распихивая их по карманам брюк."})}),(0,i.jsx)(h,{title:"Отношение к божествам",children:(0,i.jsx)(n.p,{children:"Допускает существование божеств Энкража, но не верит в них, не просит благословения, не читает молитв. Она может знать религиозные тексты и историю, но не использует их в качестве источника веры. Не контактирует и не полагается на помощь Зверя греха."})}),(0,i.jsx)(h,{title:"Искупление",children:(0,i.jsx)(n.p,{children:"Не стремится к искуплению, так как в планах много дел и возможностей. Да и Линнет чувствует себя гораздо комфортнее в мире мертвых со всеми его вводными."})}),(0,i.jsx)(h,{title:"Манера общения",children:(0,i.jsx)(n.p,{children:"Не здоровается с собеседником, стараясь сразу перейти к сути. Также не прощается."})}),(0,i.jsx)(h,{title:"Страх перед Сталкером",children:(0,i.jsx)(n.p,{children:"Боится Сталкера, хоть и не признает это открыто. Иногда приходит в ступор от одного его упоминания."})}),(0,i.jsx)(h,{title:"Желание вернуть здоровье",children:(0,i.jsx)(n.p,{children:"Желает вернуть себе полное здоровье и подвижность. Мысль о том, что это ей не удастся, не допускается."})}),(0,i.jsx)(h,{title:"Отношение к смерти",children:(0,i.jsx)(n.p,{children:"Предпочитает для себя быструю смерть, чтобы не было времени на рефлексию и разочарование в себе. Да и вообще, не особенно расстроится, если этот мир погибнет. Лишь бы не тянул с этим."})}),(0,i.jsx)(h,{title:"Поиск независимости",children:(0,i.jsx)(n.p,{children:"Ищет способ обрести полную независимость от чужой энергии, но оставить возможность ее черпать."})}),(0,i.jsx)(h,{title:"Тактильность",children:(0,i.jsx)(n.p,{children:"Не тактильна и держится от собеседника на расстоянии, не допускает по возможности сближения и предупреждает об этом вытянутой рукой с тростью, а затем – словами. Отступает, если иные способы не работают."})}),(0,i.jsx)(h,{title:"Привычка цокать языком",children:(0,i.jsx)(n.p,{children:"Цокает языком, причем не обязательно при этом выказывает недовольство. Но чаще по этой причине, разумеется."})})]})}),(0,i.jsx)(r,{title:"Внешность",children:(0,i.jsxs)(j,{children:[(0,i.jsx)(n.p,{children:(0,i.jsx)(n.strong,{children:"Форма человека."})}),(0,i.jsx)(n.p,{children:"Если бы не несколько «но», то Линнет считалась бы очень красивой женщиной, но о них позже, а пока стоит остановиться на очень красивой женщине."}),(0,i.jsx)(n.p,{children:"Красота, конечно, субъективна, в глазах смотрящего, стандартны всегда менялись и другая утешительная чушь, но параметры внешности Линнет весьма привлекательны. При жизни все было наоборот: тонкие губы, большой, с крупными зубами, рот, невзрачный цвет глаз, высокий рост, отсутствие выразительной талии и округлых форм. Становилось хуже, когда грешница переедала, но совсем печально, когда в жизни Калеки появились алкоголь и вещества. Лучше бы об этом джинн вообще никогда не вспоминала. Пусть все это теперь и далеко, но не повод для честности. Так что, если кто спросит, то в верхнем мире Лин тоже была красивой."}),(0,i.jsx)(n.p,{children:"В Энкраже, движимая на подсознательном уровне комплексами по поводу внешности, которые ярко звенели в голове даже после смерти, и желанием быть лучше, Крофт основательно себя перекроила. Да так увлеклась, что на ее условными фото до смерти и после будут два разных человека. Совершенно. Из схожестей, пожалуй, высокий рост – 176 см. Но вот вес уже другой – 53 кг. Тело стройное, но не спортивное. Любая облегающая ткань легко подчеркивает фигуру. Бледная, с сероватым подтоном, кожа отдает мертвячиной, но это лично джинна никак не смущает."}),(0,i.jsx)(n.p,{children:"Теперь её волосы были густыми, длинными, даже очень, и яркими, цвета пламени, глаза – янтарь, что несвойственно гулям, поэтому Линнет часто путают с ифритом. Черты лица резкие."}),(0,i.jsx)(n.p,{children:"А что же там с «но»? А то, что теперь Линнет считает, что слишком перестаралась, и некоторые приобретенные черты ее внешности стали в нехорошем смыли излишне приковывающие внимание."}),(0,i.jsx)(n.p,{children:"Раньше особенности гулей на теле проявлялись только во время применения способностей, локализовались на участках кожи, которые чаще всего закрывались одеждой. После встречи Крофт со Сталкером на лице, груди и руке, с левой стороны, разрослась сетка черных сосудов, как очень тонких, так и весьма заметных. Кожа в этих местах потрескавшаяся и рельефная, напоминающая язвы или струпья. Периодически «рисунок» меняется, словно живой, но не уменьшается и не перемещается. Не причиняет физического дискомфорта, в отличие от травмы ноги. Из-за нее Лин хромает. Не слегка, чтобы казаться уязвимой, а иногда и вовсе без болезненного стона или вздоха не может наступить на ногу. Внешне при этом конечность цела, да и внутри никаких переломов или отсутствия костей."}),(0,i.jsx)(n.p,{children:"Недуг влияет на походку и необходимость постоянно иметь с собой трость. Крофт может идти хоть сколь уверенно, но травма делает шаг характерным."}),(0,i.jsx)(n.p,{children:"Предпочитает современную качественную одежду, в частности брючные костюмы темных оттенков. Обувь подбирает на устойчивом каблуке, как бы не было неудобно и если джинн не среди диких мест. Заметными акцентами в повседневном виде, помимо упомянутого ранее, являются очки. Круглые, квадратные, прямоугольные, овальные, с резной или обычной оправой, с почти любого цвета линзами – в дело пойдет все. Это не просто стильно, но и защищает от света. А вот драгоценности не имеют большого значения. За пределами лавки носит еще и наплечную сумку с необходимыми вещами."}),(0,i.jsx)(n.p,{children:"Волосы «от природы» вьются крупными локонами, чаще всего распущены. Прически грешница делать не особенно умеет и не хочет. Когда необходимо убрать – заплетает косу или убирает в высокий хвост."}),(0,i.jsx)(n.p,{children:"Тембр голоса по высоте средний, чистый, но лишенный мягкости и тепла. Чаще звучит резкость и неприязнь, даже если не к кому ее испытывать. Отличная дикция, большой словарный запас. Иногда в речи присутствуют устаревшие конструкции."}),(0,i.jsx)(n.p,{children:"Во время применения способностей радужка глаз меняется с янтарного на белый. Зрачок мутнеет до бледного серого цвета."}),(0,i.jsx)(n.p,{children:(0,i.jsx)(n.strong,{children:"Форма гуля."})}),(0,i.jsx)(n.p,{children:"Меняется оттенок кожи на более серый, а сама кожа натягивается на кости, делая вид Линнет изможденным, иссохшим. Уши заостряются и вытягиваются, вырастают длинные когти на руках, ноги становятся похожими на звериные лапы без шерсти. Зубы заостряются и немного увеличиваются, цвет глаз меняется с янтарного на белый. Рост при этом не меняется. Хромота остается, а темная сетка вен расходится по всему телу."})]})}),(0,i.jsx)(r,{title:"Навыки и умения",children:(0,i.jsxs)(d,{children:[(0,i.jsxs)(h,{title:"Языки",children:[(0,i.jsx)(n.p,{children:"Еще при смертной жизни Линнет выучила английский, немецкий и французский языки. Свободно на них изъясняется, читает и пишет. К ним присоединился современный Квелларий, но уже, соответственно, после смерти. Имре, наставник Лин, был довольно старым джинном. Как он рассказывал, однажды заключил контракт с носителем языка, и условием как раз было обучение. Конечно, «учителя» пришлось поискать, несколько кандидатов на такую роль попросту отказывались."}),(0,i.jsx)(n.p,{children:"Так что с современным Квелларием тоже нет особых проблем, однако куда сложнее дела обстоят со средним Квелларием, который Крофт учит в настоящее время. Можно сказать, что она в самом начале. Имре как-то говорил, что начнет обучение, но так и не успел передать и крупицу знаний. Теперь те самые крупицы Линнет старается найти сама."})]}),(0,i.jsx)(h,{title:"Зельеварение",children:(0,i.jsx)(n.p,{children:"Умеет приготовить зелье на базовом уровне, в основном, для личных нужд. Редко удается что-то продать, так как имеются другие дельцы. На удивление, в этом ремесле гуль не торопится преуспеть, но и забывать не хочет."})}),(0,i.jsx)(h,{title:"Флора и фауна Энкража",children:(0,i.jsx)(n.p,{children:"Не идеально, но знает флору и фауну Энкража, так как они чаще остального являются целью контракта, а также были предметом торговли, когда Лин была с «семьей»."})}),(0,i.jsx)(h,{title:"Леди-навыки",children:(0,i.jsx)(n.p,{children:"Пакет знаний и умений леди: грамота, письмо, верховая езда, этикет. Некоторое из перечисленного применяется редко."})}),(0,i.jsx)(h,{title:"Плавание",children:(0,i.jsx)(n.p,{children:"Умеет плавать."})}),(0,i.jsx)(h,{title:"Подделка почерка",children:(0,i.jsx)(n.p,{children:"Этому навыку грешница обучилась уже в посмертии у наставника. При небольшой тренировке вполне успешно подделает стиль, положение и особенности письма."})}),(0,i.jsx)(h,{title:"Наблюдательность",children:(0,i.jsx)(n.p,{children:"Стоит отнести это именно к навыкам, а не чертам характера, так как за обе жизни Линнет очень долго стояла в стороне и изучала других."})}),(0,i.jsx)(h,{title:"Начитанность",children:(0,i.jsx)(n.p,{children:"Знание истории Энкража и людского мира (не в мельчайших деталях, разумеется, до некоторых трудов и вовсе не добраться). Чтобы быть едва ли заменимой и значимой, важной, в том числе в своих делах, Крофт цедила знания из всех доступных источников."})}),(0,i.jsx)(h,{title:"Эйдетическая память",children:(0,i.jsx)(n.p,{children:"Это не абсолютная память, самые свежие, четкие и полные образы сохраняются в сознании до 2-3 месяцев, а дальше уже как получится."})}),(0,i.jsx)(h,{title:"Базовая готовка",children:(0,i.jsx)(n.p,{children:"Зачем, спрашивается, готовить сырое мясо трупа? Не за чем, но если хочется более-менее обычной еды, то приходится немного заморочиться. Так как просить некого, живет Лин одна, пришлось учиться. Но другим ее стряпню лучше не пробовать."})}),(0,i.jsx)(h,{title:"Навыки выживания в среде Энкража",children:(0,i.jsx)(n.p,{children:"Очень быстро джинн поняла, что Энкраж – место агрессивное и опасное. Особенно это стало актуально после получения травмы."})}),(0,i.jsx)(h,{title:"Консервация",children:(0,i.jsx)(n.p,{children:"Оказалась необходимой для соблюдения товарного вида тем же частям зверей."})}),(0,i.jsx)(h,{title:"Производство сигарет",children:(0,i.jsx)(n.p,{children:"Производство в малых количествах сигарет для личного потребления."})})]})}),(0,i.jsx)(r,{title:"Слабости",children:(0,i.jsxs)(d,{children:[(0,i.jsx)(h,{title:"Расовые слабости",children:(0,i.jsx)(n.p,{children:"Все расовые слабости присутствуют в Лин, и особенного иммунитета к ним нет. Очки она использует по прямому назначению, особым ночным зрением не обладает. Даже косвенно лучи света от любого источника причиняют боль. Дефектная ЭПФО проявлена внешне независимо от условий. Сосуд в виде серебряного открывающегося кулона без фотографии внутри. Интересный факт: когда Линнет находится внутри сосуда, на месте фото проявляется ее лицо. Крофт прячет старательно и периодически меняет тайники в пределах «своей» территории. Неизбежны и узы контракта, а также зависимость от чужой энергии."})}),(0,i.jsx)(h,{title:"Инвалидность",children:(0,i.jsx)(n.p,{children:"Визуально нога целая, однако практически недееспособна. При ходьбе Линнет испытывает сильные, разного рода, боли, которые, правда, затихают, но это не влияет особо на скорость передвижения. А иногда конечность и вовсе отнимается, теряя всякую чувствительность и хоть какую-то опору. Из-за этого грешница не может бегать, быстро ходит только при острой необходимости, до скрежета сжимая зубы. Полагается на трость. Также не может полноценно сражаться ни в одном из обликов, а в пелене чужих образов, если те умеют двигаться, всегда будет хромать."})}),(0,i.jsx)(h,{title:"Физическая слабость",children:(0,i.jsx)(n.p,{children:"Отсутствие физических нагрузок, тренировок и малая мобильность делают Крофт физически слабее грешников ее возраста, даже если те не особенно не совершенствуют свое тело."})}),(0,i.jsx)(h,{title:"Страх повторного наказания",children:(0,i.jsx)(n.p,{children:"Джинн можно назвать смелой, однако есть ряд вещей, которые вводят либо в ступор, либо в панику. Одним из таких является Сталкер, который, когда явится, то не для того, чтобы забрать травму, которую сам же нанес. Скорее он добавит еще чего, чтобы ухудшить положение Крофт. Это способно остановить ее действия и поступки, развернуться, сдаться и запереться ото всех в страхе получить аудиенцию с палачом."})}),(0,i.jsx)(h,{title:"Страх не вернуть дееспособность",children:(0,i.jsx)(n.p,{children:"Страх никогда не вернуть себе полную дееспособность и прежнюю привлекательность. Эта тема способна вывезти Лин из себя так, что она перестанет трезво оценивать свои способности и положение. В противовес предыдущему страху она может совершить необдуманные поступки в надежде больше никогда не испытывать мук боли и терпеть насмешки других."})}),(0,i.jsx)(h,{title:"Страх не достичь значимых результатов",children:(0,i.jsx)(n.p,{children:"Страх не достичь значимых результатов, оказаться в том же положении, что и при жизни. Иначе все старания, все это копание в грязи и дерьме ничего не значат."})}),(0,i.jsx)(h,{title:"Характер",children:(0,i.jsx)(n.p,{children:"Как бы это не звучало, но ершистый характер, несмотря на амбиции, мешает в жизни не хуже травмы, где-то замедляет или вовсе лишает желаемого результата."})}),(0,i.jsx)(h,{title:"Отсутствие иммунитета к магии",children:(0,i.jsx)(n.p,{children:"Отсутствие особенного иммунитета к любого вида магии. Особенно Лин старательно избегает тех, кто может воздействовать на разум как напрямую, так и косвенно."})})]})}),(0,i.jsx)(r,{title:"Связанные персонажи",children:(0,i.jsx)(d,{children:(0,i.jsx)(h,{title:"Шарлотта Клоуд",children:(0,i.jsx)(n.p,{children:"Мать, которая, в некотором смысле, винила себя в том, какой дочь стала, но могла ли она иначе при всех вводных? С ней у Лин были наиболее близкие отношения. Связаны через украшения: серьги и кулон на цепочке (жемчуг, белое золото)."})})})})]}),(0,i.jsx)(x,{children:(0,i.jsx)(n.p,{children:"Закрой дверь с той стороны"})})]})}function s(e,i){throw Error("Expected "+(i?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}e.s(["default",0,function(e={}){let{wrapper:s}={...(0,l.useMDXComponents)(),...e.components};return s?(0,i.jsx)(s,{...e,children:(0,i.jsx)(n,{...e})}):n(e)}])}]);